from datetime import datetime, timezone
from django.core.management.base import BaseCommand, CommandError
from core.models import EncroachmentAlert

# Explicit taxonomy of alerts generated by ai_simulation.py and prototype seed scripts
PROTOTYPE_SIMULATION_ALERT_TYPES = [
    'Illegal Structure',
    'Wall Construction',
    'Waterbody Incursion',
    'Forest Encroachment',
    'Excavation Work',
    'Survey Warning',
    'Roadside Margin Occupation',
    'Permanent Boundary Wall Trespass on Road Margin',
    'Government Occupation Threat',
    'Commercial Structure on Govt Poramboke',
    'Forest Occupation Threat',
    'Waterbody Occupation Threat',
    'Waterbody Basin Encroachment',
    'Heavy Vehicle Workshop Shoulder Breach',
    'Roadside Occupation Threat',
    'Temple Occupation Threat',
    'Footpath & Pedestrian Right-of-Way Blockade'
]

# Strict UTC cutoff: prototype generation concluded at 2026-10-27 07:37:53 UTC
PROTOTYPE_CUTOFF_DATETIME = datetime(2026, 10, 27, 12, 0, 0, tzinfo=timezone.utc)


class Command(BaseCommand):
    help = (
        'One-off management command to safely flag prototype alerts as synthetic. '
        'Selects alerts based on explicit simulation taxonomy and prototype generation timestamp window.'
    )

    def add_arguments(self, parser):
        parser.add_argument(
            '--confirm',
            action='store_true',
            help='Confirm execution of synthetic flag update.'
        )
        parser.add_argument(
            '--expected-count',
            type=int,
            required=True,
            help='Exact number of alerts expected to be flagged.'
        )

    def handle(self, *args, **options):
        confirm = options['confirm']
        expected_count = options['expected_count']

        already_flagged = EncroachmentAlert.objects.filter(is_synthetic=True).count()
        if already_flagged > 0:
            raise CommandError(
                f"[ABORTED] Safety guard tripped: {already_flagged} alerts are already flagged as synthetic."
            )

        # Real criterion: signature match on simulation taxonomy and creation window
        prototype_qs = EncroachmentAlert.objects.filter(
            detection_date__lte=PROTOTYPE_CUTOFF_DATETIME,
            alert_type__in=PROTOTYPE_SIMULATION_ALERT_TYPES,
            is_synthetic=False
        )
        matched_count = prototype_qs.count()

        # Sanity check against entire table
        total_in_db = EncroachmentAlert.objects.count()
        if matched_count != total_in_db:
            self.stdout.write(
                self.style.WARNING(
                    f"[NOTICE] Database has {total_in_db} total alerts; signature criterion matched {matched_count} prototype alerts."
                )
            )

        if matched_count != expected_count:
            raise CommandError(
                f"[ABORTED] Signature count mismatch: expected {expected_count} alerts, but criterion matched {matched_count}."
            )

        if not confirm:
            self.stdout.write(
                self.style.WARNING(
                    f"[DRY RUN] Found exactly {matched_count} alerts matching prototype simulation signature. "
                    "Re-run with --confirm to apply."
                )
            )
            return

        updated = prototype_qs.update(is_synthetic=True)
        self.stdout.write(
            self.style.SUCCESS(
                f"[SUCCESS] Successfully flagged {updated} prototype alerts as is_synthetic=True based on simulation signature."
            )
        )
